/// <summary>
/// Service class for transfer picking list generation service task
/// </summary>
class METTransferPickingListGenerationTaskService extends SysOperationServiceBase
{

    boolean lineSubstituted = false;

}

Method.Source:
    /// <summary>
    /// If the transfer order is a CSD or a Cross dock order, then it should be auto received
    /// </summary>
    /// <param name = "_transferId">Transfer order number to check if this can be auto-received</param>
    /// <returns>Yes if the order should be auto received, otherwise false</returns>
    private NoYes shouldAutoReceive(InventTransferId _transferId)
    {
        METInventTransferTableExt   metInventTransferTableExt;
        InventTransferTable         inventTransferTable;
        NoYes ret = NoYes::No;

        select TransferType from metInventTransferTableExt
            exists join inventTransferTable
            where inventTransferTable.RecId == metInventTransferTableExt.InventTransferTable
            && inventTransferTable.TransferId == _transferId;
        
        if (metInventTransferTableExt.TransferType == METCrossDockTransferType::CrossDock || metInventTransferTableExt.TransferType == METCrossDockTransferType::CSD)
        {
            ret = NoYes::Yes;
        }

        return ret;
    }

    private container pick(METTransferPickingListGenerationTaskContract _dataContract)
    {
        InventTransferParmTable         inventTransferParmTable;
        InventTransferParmLine          inventTransferParmLine;
        InventTransferUpd               inventTransferUpd;
        InventTransferLine              inventTransferLineCancel;
        METInventTransferLine           metInventTransferLineCancel;
        
        //CB238 - xDock
        InventTransferTable inventTransferTable = InventTransferTable::find(_dataContract.parmTransferId());

        if (inventTransferTable.metInventTransferTableExt().AllowBackorder == false)
        {
            while select forupdate metInventTransferLineCancel
                join inventTransferLineCancel
                    where inventTransferLineCancel.RecId == metInventTransferLineCancel.InventTransferLine  &&
                        inventTransferLineCancel.TransferId == inventTransferTable.TransferId
            {
                if (inventTransferLineCancel.displayQtyReservedPhysical() == 0)
                {
                    inventTransferLineCancel.selectForUpdate(true);
                    inventTransferLineCancel.QtyRemainShip = inventTransferLineCancel.QtyTransfer;
                    inventTransferLineCancel.updateDeliverRemainder(); //std code contains ttsbegin and ttscommit

                    info(strFmt("@MET:NoStockTO", inventTransferLineCancel.TransferId, inventTransferLineCancel.ItemId));
                    metInventTransferLineCancel.OrderExtractStatus = METOrderExtractStatus::Extracted;
                    metInventTransferLineCancel.update();
                }
            }
        }
        inventTransferParmTable.TransferId          = _dataContract.parmTransferId();
        inventTransferParmTable.UpdateType          = InventTransferUpdateType::PickingList;
        // CB715_TransferOrderExtract
        // generate picklist for the order lines where reservation has occurred
        //inventTransferParmTable.PickUpdateQty       = InventTransferPickUpdateQty::AvailableQty;
        inventTransferParmTable.PickUpdateQty       = InventTransferPickUpdateQty::ReservedQty;
        inventTransferParmTable.Reservation         = NoYes::Yes;
        inventTransferParmTable.EditLines           = NoYes::Yes;
        inventTransferParmTable.TransDate           = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        
        // CB238 - xDock process - Mark auto-reserve for cross dock and CSD transfer orders
        inventTransferParmTable.AutoReceiveQty = this.shouldAutoReceive(_dataContract.parmTransferId());

        // CB715_TransferOrderExtract
        // This will populate inventTransferParmLine with only TO lines where extraction status=”Ready for extract” only.
        //inventTransferUpd = InventTransferUpdPick::NewParmBuffer(inventTransferParmTable);
        inventTransferUpd = InventTransferUpdPick::METNewParmBuffer(inventTransferParmTable);
        
        select firstonly RecId from inventTransferParmLine
            where inventTransferParmLine.ParmId == inventTransferParmTable.ParmId
                && inventTransferParmLine.TransferId == inventTransferParmTable.TransferId;

        if(inventTransferParmLine.RecId)
        {
            inventTransferUpd.run();
        }

        return [inventTransferUpd.parmInventTransferJour(), inventTransferParmTable];
    }

    private void postSalesOrder(InventTransferId _transferId)
    {
        InventTransferTable transferTable;
        METInventTransferTableExt transferTableExt;

        select transferTable
            join transferTableExt
            where transferTableExt.InventTransferTable == transferTable.RecId
            && transferTable.TransferId == _transferId
            && transferTableExt.SalesId != '';

        SalesTable salesTable;
        METSalesPickingListGenerationTaskController         salesPickingListGenerationTaskController;
        METSalesPickingListGenerationTaskContract           salesPickingListGenerationTaskContract;

        if(transferTableExt)
        {
            salesTable = SalesTable::find(transferTableExt.SalesId);
        }

        if(salesTable)
        {
            METStockReservation::construct(salesTable).process();
        }
        
    }

    /// <summary>
    /// processing logic
    /// </summary>
    /// <param name = "_dataContract">The data contract</param>
    public void process(METTransferPickingListGenerationTaskContract _dataContract)
    {
        InventTransferJour inventTransferJour;
        InventTransferParmTable inventTransferParmTable;

        try
        {
            ttsbegin;
            [InventTransferJour, inventTransferParmTable] = this.pick(_dataContract);
            
            //CB-238 - Internal cross dock : Perform substitution re-pick of transfer order lines when
            //1. Supply from transfer order is enabled
            this.applySubstitutions(_dataContract.parmTransferId());
            
            if (lineSubstituted)
            {
                [InventTransferJour, inventTransferParmTable] = this.pick(_dataContract);
            }

            WMSPickingRoute wmsPickingRoute;

            select firstonly wmsPickingRoute
                where wmsPickingRoute.parmid == inventTransferParmTable.ParmId;

            WMSPickingRouteID pickRouteId;

            if (wmsPickingRoute)
            {
                METOrderShipmentLoadCreation metOrderShipmentloadCreation = METOrderShipmentLoadCreation::construct(METOrderTransactionType::TransferOrder,
                                                                                                                            _dataContract.parmTransferId());
                metOrderShipmentloadCreation.createShippmentLoad(true, false);
                pickRouteId = wmsPickingRoute.pickingRouteID;
                
                //CB238 - xDock perform sales reservation once the transfer order picking list is created.
                //this.postSalesOrder(_dataContract.parmTransferId());

                if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METPicklistExtractionBusinessEvent)))
                {
                    METPicklistExtractionBusinessEvent::newFromWMSPickingRoute(wmsPickingRoute).send();
                }
                else
                {
                    error("@MET:PickListExtractionBusinessEventNotEnabled");
                }
            }

            ttscommit;

            //CB628 - Send order to TMS after the pick list is posted.
            METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::TransferOrderPickinglist, wmsPickingRoute, wmsPickingRoute.pickingRouteID).run();
        }
        catch
        {
            error ("@WAX:UpdateCancelled");
        }

        if (!inventTransferJour)
        {
            //Update transfer header extraction status
            METInventTransferTableExt::UpdateExtractionStatus(_dataContract.parmTransferId());
        }
    }

    private void applySubstitutions(InventTransferId _transferId)
    {
        InventTransferLine transferLine;
        METInventTransferLine metTransferLine;
        InventTransferTable transferTable;
        METSubstitutionSalesLineProcess subSalesLineProcess;
        
        lineSubstituted = false;

        while select transferLine
            where transferLine.TransferId == _transferId
            join metTransferLine
            where metTransferLine.InventTransferLine == transferLine.RecId
            && metTransferLine.AllowSubstitution == NoYes::Yes
        {
            if(transferLine.qtyReservedOnOrder() == 0)
            {
                SalesLine salesLineLoc = metTransferLine.salesLine_InventTransId();

                //if (salesLineLoc.mcrSalesQtyReserved() == transferLine.QtyTransfer && salesLineLoc.mcrSalesQtyReserved() <= transferLine.QtyTransfer)
                {
                    subSalesLineProcess = METSubstitutionSalesLineProcess::construct(salesLineLoc, true, true, true);

                    if (subSalesLineProcess.run())
                    {
                        lineSubstituted = true;
                        //salesLineLoc.reread();
                        //subSalesLineProcess = METSubstitutionSalesLineProcess::construct(salesLineLoc, true, true, true);
                    }
                }
            }
        }


    }
